package pflag

import (
	"fmt"
	"net"
)

func lokiCases() {
	lokiCase("c1", "change", "IP flag given --ip= with empty value", func() interface{} {
		var p net.IP
		fs := NewFlagSet("t", ContinueOnError)
		fs.IPVar(&p, "ip", nil, "usage")
		e := fs.Parse([]string{"--ip="})
		return lokiAll(p.String(), fmt.Sprint(e))
	})
	lokiCase("c2", "change", "IP flag given --ip= with whitespace-only value", func() interface{} {
		var p net.IP
		fs := NewFlagSet("t", ContinueOnError)
		fs.IPVar(&p, "ip", nil, "usage")
		e := fs.Parse([]string{"--ip=   "})
		return lokiAll(p.String(), fmt.Sprint(e))
	})
	lokiCase("c3", "change", "FlagSet.Set ip with empty string", func() interface{} {
		var p net.IP
		fs := NewFlagSet("t", ContinueOnError)
		fs.IPVar(&p, "ip", nil, "usage")
		e := fs.Set("ip", "")
		return lokiAll(p.String(), fmt.Sprint(e))
	})

	lokiCase("k1", "keep", "IP flag --ip=abc invalid value error", func() interface{} {
		var p net.IP
		fs := NewFlagSet("t", ContinueOnError)
		fs.IPVar(&p, "ip", nil, "usage")
		e := fs.Parse([]string{"--ip=abc"})
		return lokiAll(p.String(), fmt.Sprint(e))
	})
	lokiCase("k2", "keep", "IP flag --ip=192.168.1.1 valid IPv4", func() interface{} {
		var p net.IP
		fs := NewFlagSet("t", ContinueOnError)
		fs.IPVar(&p, "ip", nil, "usage")
		e := fs.Parse([]string{"--ip=192.168.1.1"})
		return lokiAll(p.String(), fmt.Sprint(e))
	})
	lokiCase("k3", "keep", "IP flag --ip= with surrounding spaces in value", func() interface{} {
		var p net.IP
		fs := NewFlagSet("t", ContinueOnError)
		fs.IPVar(&p, "ip", nil, "usage")
		e := fs.Parse([]string{"--ip= 10.0.0.1 "})
		return lokiAll(p.String(), fmt.Sprint(e))
	})
	lokiCase("k4", "keep", "IP flag --ip=FE80::1 uppercase IPv6", func() interface{} {
		var p net.IP
		fs := NewFlagSet("t", ContinueOnError)
		fs.IPVar(&p, "ip", nil, "usage")
		e := fs.Parse([]string{"--ip=FE80::1"})
		return lokiAll(p.String(), fmt.Sprint(e))
	})
	lokiCase("k5", "keep", "ipValue.Set with padded ::1", func() interface{} {
		var p net.IP
		v := newIPValue(nil, &p)
		e := v.Set("  ::1  ")
		return lokiAll(p.String(), fmt.Sprint(e))
	})
	lokiCase("k6", "keep", "GetIP on flag with default 1.2.3.4", func() interface{} {
		var p net.IP
		fs := NewFlagSet("t", ContinueOnError)
		fs.IPVar(&p, "ip", net.ParseIP("1.2.3.4"), "usage")
		ip, err := fs.GetIP("ip")
		return lokiAll(ip.String(), fmt.Sprint(err))
	})
	lokiCase("k7", "keep", "ipConv with empty string", func() interface{} {
		return fmt.Sprint(ipConv(""))
	})
	lokiCase("k8", "keep", "ipConv with 1.2.3.4", func() interface{} {
		return fmt.Sprint(ipConv("1.2.3.4"))
	})
	lokiCase("k9", "keep", "ipValue Type name", func() interface{} {
		var p net.IP
		return newIPValue(nil, &p).Type()
	})
	lokiCase("k10", "keep", "FlagSet.Set ip with bogus value error", func() interface{} {
		var p net.IP
		fs := NewFlagSet("t", ContinueOnError)
		fs.IPVar(&p, "ip", nil, "usage")
		return fmt.Sprint(fs.Set("ip", "bogus"))
	})
	lokiCase("k11", "keep", "IP flag default value string", func() interface{} {
		fs := NewFlagSet("t", ContinueOnError)
		fs.IP("ip", net.ParseIP("10.1.1.1"), "usage")
		return fs.Lookup("ip").DefValue
	})
	lokiCase("k12", "keep", "FlagUsages for IP flag", func() interface{} {
		var p net.IP
		fs := NewFlagSet("t", ContinueOnError)
		fs.IPVar(&p, "ip", nil, "usage")
		return fs.FlagUsages()
	})
}

