package cobra

import "fmt"

func lokiCases() {
	lokiCase("c1", "change", "getCompletions on traverse root, args len 2 cap 8 [x, empty]: args slice after call", func() interface{} {
		root := &Command{Use: "root", TraverseChildren: true, Run: emptyRun}
		args := make([]string, 2, 8)
		args[0] = "x"
		_, comps, dir, err := root.getCompletions(args)
		return lokiAll(args, comps, dir.string(), fmt.Sprint(err))
	})
	lokiCase("c2", "change", "getCompletions on non-traverse root, args len 2 cap 8 [x, empty]: args slice after call", func() interface{} {
		root := &Command{Use: "root", Run: emptyRun}
		args := make([]string, 2, 8)
		args[0] = "x"
		_, comps, dir, err := root.getCompletions(args)
		return lokiAll(args, comps, dir.string(), fmt.Sprint(err))
	})
	lokiCase("c3", "change", "getCompletions issue example: args [x] with spare capacity, args slice after call", func() interface{} {
		root := &Command{Use: "root", TraverseChildren: true, Run: emptyRun}
		args := make([]string, 1, 4)
		args[0] = "x"
		_, comps, dir, err := root.getCompletions(args)
		return lokiAll(args, comps, dir.string(), fmt.Sprint(err))
	})

	lokiCase("k1", "keep", "getCompletions traverse root, ValidArgsFunction sees args for [x]", func() interface{} {
		root := &Command{
			Use:              "root",
			TraverseChildren: true,
			Run:              emptyRun,
			ValidArgsFunction: func(c *Command, a []string, tc string) ([]Completion, ShellCompDirective) {
				return []Completion{fmt.Sprint(a)}, ShellCompDirectiveDefault
			},
		}
		_, comps, dir, err := root.getCompletions([]string{"x"})
		return lokiAll(comps, dir.string(), fmt.Sprint(err))
	})
	lokiCase("k2", "keep", "getCompletions non-traverse root, ValidArgsFunction sees [x y]", func() interface{} {
		root := &Command{
			Use: "root",
			Run: emptyRun,
			ValidArgsFunction: func(c *Command, a []string, tc string) ([]Completion, ShellCompDirective) {
				return []Completion{fmt.Sprint(a)}, ShellCompDirectiveDefault
			},
		}
		_, comps, dir, err := root.getCompletions([]string{"x", "y", ""})
		return lokiAll(comps, dir.string(), fmt.Sprint(err))
	})
	lokiCase("k3", "keep", "getCompletions subcommand prefix ap completes apple", func() interface{} {
		root := &Command{Use: "root", Run: emptyRun}
		root.AddCommand(&Command{Use: "apple", Short: "a fruit", Run: emptyRun})
		_, comps, dir, err := root.getCompletions([]string{"ap"})
		return lokiAll(comps, dir.string(), fmt.Sprint(err))
	})
	lokiCase("k4", "keep", "getCompletions unknown subcommand nope error", func() interface{} {
		root := &Command{Use: "root", Run: emptyRun}
		root.AddCommand(&Command{Use: "apple", Short: "a fruit", Run: emptyRun})
		_, comps, dir, err := root.getCompletions([]string{"nope", "x"})
		return lokiAll(comps, dir.string(), fmt.Sprint(err))
	})
	lokiCase("k5", "keep", "getCompletions ValidArgs [xray] with X uppercase prefix", func() interface{} {
		root := &Command{Use: "root", Run: emptyRun, ValidArgs: []string{"xray"}}
		_, comps, dir, err := root.getCompletions([]string{"X"})
		return lokiAll(comps, dir.string(), fmt.Sprint(err))
	})
	lokiCase("k6", "keep", "getCompletions ValidArgs [xray xenon] with [x x] repeated args", func() interface{} {
		root := &Command{Use: "root", Run: emptyRun, ValidArgs: []string{"xray", "xenon"}}
		_, comps, dir, err := root.getCompletions([]string{"x", "x"})
		return lokiAll(comps, dir.string(), fmt.Sprint(err))
	})
	lokiCase("k7", "keep", "getCompletions flag name completion --he", func() interface{} {
		root := &Command{Use: "root", Run: emptyRun}
		_, comps, dir, err := root.getCompletions([]string{"--he"})
		return lokiAll(comps, dir.string(), fmt.Sprint(err))
	})
	lokiCase("k8", "keep", "getCompletions empty toComplete on bare root", func() interface{} {
		root := &Command{Use: "root", Run: emptyRun}
		_, comps, dir, err := root.getCompletions([]string{""})
		return lokiAll(comps, dir.string(), fmt.Sprint(err))
	})
	lokiCase("k9", "keep", "initCompleteCmd with [__complete x] adds one command", func() interface{} {
		root := &Command{Use: "root", Run: emptyRun}
		root.initCompleteCmd([]string{"__complete", "x"})
		return len(root.Commands())
	})
	lokiCase("k10", "keep", "initCompleteCmd with [x] adds no command", func() interface{} {
		root := &Command{Use: "root", Run: emptyRun}
		root.initCompleteCmd([]string{"x"})
		return len(root.Commands())
	})
	lokiCase("k11", "keep", "ShellCompDirective NoFileComp string", func() interface{} {
		return ShellCompDirectiveNoFileComp.string()
	})
}

